				nj := j + i + k - 1
				if nj > x {
					break
				}
				dp[i+k][nj] += dp[i][j] * pow[i+k-1][k] % Mod * ModCombination(i+k, k)
				dp[i+k][nj] %= Mod
			}
		}
	}

	ans := int64(0)
	for j := 1; j <= x; j++ {
		ans += dp[n][j]
		ans %= Mod
	}
